from pathlib import Path
import subprocess
import yaml

path = Path('.github/workflows/project-os-chg120-final-verify-v15.yml')
doc = yaml.safe_load(path.read_text())
assert isinstance(doc, dict)
runs = []
def walk(value):
    if isinstance(value, dict):
        if isinstance(value.get('run'), str):
            runs.append(value['run'])
        for item in value.values():
            walk(item)
    elif isinstance(value, list):
        for item in value:
            walk(item)
walk(doc)
for index, run in enumerate(runs, 1):
    result = subprocess.run(['bash', '-n'], input=run, text=True, capture_output=True)
    if result.returncode "'!= 0:
        raise SystemExit(f'"'bash -n failed for run block {index}: {result.stderr}')
print(f'yaml_parse=pass bash_blocks={len(runs)}')
